# title, concept, common mistake, runnable example, practice, expected result, question, correct, wrong answers
LESSONS = [
('Установка, модуль и первый запуск', 'Проверьте go version, создайте пустую папку и выполните go mod init example/hello. Файл main.go с package main и функцией main запускается командой go run . Модуль задаёт границу проекта и имя для импорта собственных пакетов.', 'Команду go run . выполняют внутри папки с go.mod. Если терминал не видит go, проверьте установку и PATH; сайт не запускает ваш код.', 'package main\nimport "fmt"\nfunc main() { fmt.Println("Привет, Go") }', 'Создайте модуль example/hello, выведите две строки и сохраните команды и фактический вывод.', 'go run . выводит ваши строки без ошибок.', 'Что создаёт go mod init?', 'Файл go.mod', ['Исполняемый файл', 'Новый HTTP сервер']),
('Переменные, константы и типы', 'Go проверяет типы при компиляции. var задаёт переменную, := сокращает объявление внутри функции, const задаёт константу. Нулевое значение int равно 0, bool равно false, string равна пустой строке.', 'Короткое объявление := нельзя использовать на уровне пакета. Не полагайтесь на неявное преобразование int в string: это разные значения.', 'package main\nimport "fmt"\nfunc main() { age := 25; const unit = "лет"; fmt.Println(age, unit) }', 'Создайте переменные возраста и имени, выведите их, затем измените возраст и повторите вывод.', 'После присваивания виден новый возраст.', 'Где допустимо :=?', 'Внутри функции', ['Только вне функций', 'Только в go.mod']),
('Условия и циклы', 'if проверяет логическое выражение без круглых скобок. for — единственная конструкция цикла в Go: она заменяет и привычный for, и while. switch помогает читать несколько взаимоисключающих ветвей.', 'Условие if не принимает число вместо bool. В цикле проверяйте граничные значения: ноль повторений, один и последний допустимый индекс.', 'package main\nimport "fmt"\nfunc main() { sum := 0; for i := 1; i <= 3; i++ { sum += i }; if sum == 6 { fmt.Println("готово") } }', 'Посчитайте сумму чисел от 1 до 10 и отдельно проверьте цикл с верхней границей 0.', 'Сумма 1..10 равна 55; пустой диапазон не добавляет значений.', 'Сколько основных конструкций цикла есть в Go?', 'Одна: for', ['Две: for и while', 'Три: for, while и repeat']),
('Функции и область видимости', 'Функция принимает типизированные параметры и возвращает значение после имени параметров. Можно вернуть несколько значений, например результат и ошибку. Имя внутри блока живёт только до закрывающей фигурной скобки.', 'Не скрывайте внешнюю переменную через :=, если хотели её изменить. Для публичной функции имя начинается с заглавной буквы; внутренние помощники могут быть строчными.', 'package main\nimport "fmt"\nfunc add(a, b int) int { return a + b }\nfunc main() { fmt.Println(add(2, 3)) }', 'Напишите функцию max(a, b int) int и проверьте равные, положительные и отрицательные значения.', 'Функция возвращает большее число, для равных — само число.', 'Где виден параметр функции?', 'Внутри этой функции', ['Во всех пакетах', 'Только в main']),
('Строки и Unicode', 'string хранит байты в UTF-8, поэтому len считает байты, а не обязательно символы. range по строке выдаёт rune — кодовую точку Unicode. Для вывода человеку часто достаточно fmt.Println, а для посимвольной обработки нужен range.', 'Не индексируйте русское слово как массив букв: s[0] — первый байт. Для количества кодовых точек используйте utf8.RuneCountInString; графемы могут состоять из нескольких точек.', 'package main\nimport ("fmt"; "unicode/utf8")\nfunc main() { s := "Go и мир"; fmt.Println(len(s), utf8.RuneCountInString(s)) }', 'Сравните len и число rune у слов Go и Привет; объясните разницу.', 'Для ASCII числа равны; для кириллицы число байт больше.', 'Что возвращает len(string)?', 'Число байт', ['Число слов', 'Число видимых символов']),
('Массивы и срезы', 'Массив имеет длину как часть типа: [3]int и [4]int — разные типы. Срез []int описывает последовательность поверх массива; append может выделить новый массив, поэтому возвращённый срез нужно сохранить.', 'Не меняйте один срез, предполагая, что другой всегда независим: они могут разделять память. Если нужна копия, выделите новый срез и вызовите copy.', 'package main\nimport "fmt"\nfunc main() { a := []int{2, 4}; a = append(a, 6); fmt.Println(len(a), a[2]) }', 'Соберите срез из пяти чисел, добавьте шестое, посчитайте сумму через range и проверьте пустой срез.', 'После append длина увеличивается на один; сумма учитывает все элементы.', 'Что возвращает append?', 'Новый заголовок среза', ['Число добавленных элементов', 'Исходный массив']),
('Карты и проверка ключа', 'map связывает ключ и значение. Чтение отсутствующего ключа возвращает нулевое значение, поэтому используйте форму value, ok := m[key], чтобы отличить отсутствие от настоящего нуля. Порядок обхода map не гарантируется.', 'Не стройте тест на порядке range по map. Обычная map не подходит для одновременной записи из нескольких горутин без синхронизации.', 'package main\nimport "fmt"\nfunc main() { scores := map[string]int{"Аня": 0}; v, ok := scores["Аня"]; fmt.Println(v, ok) }', 'Посчитайте частоту слов в коротком списке и отдельно проверьте отсутствующее слово через ok.', 'Существующее слово со счётом 0 отличается от отсутствующего ключа.', 'Как проверить наличие ключа?', 'Вторым значением ok', ['Через len(m)', 'По порядку обхода']),
('Структуры данных', 'struct объединяет поля с разными типами. Литерал с именованными полями легче читать и безопаснее менять. Вложенные структуры помогают описывать данные без глобальных переменных.', 'Экспортируются только поля с заглавной буквы. Для JSON-кодирования неэкспортируемые поля не видны; это частая причина пустого объекта.', 'package main\nimport "fmt"\ntype Task struct { Title string; Done bool }\nfunc main() { t := Task{Title: "Прочитать главу"}; fmt.Println(t.Title, t.Done) }', 'Опишите структуру Book с названием, автором и страницами; создайте два значения и выведите их.', 'Поля каждого экземпляра независимы, незаполненный bool равен false.', 'Что объединяет struct?', 'Поля разных типов', ['Только строки', 'Только функции']),
('Методы и указатели', 'Метод — функция с получателем. Получатель-значение получает копию небольшого объекта, а указатель позволяет изменить исходную структуру. Go автоматически упрощает запись вызова метода для адресуемой переменной.', 'Выбирайте указатель, когда метод меняет состояние. Не храните указатель на временный объект без ясной причины; различайте копирование значения и общий доступ.', 'package main\nimport "fmt"\ntype Counter struct { N int }\nfunc (c *Counter) Inc() { c.N++ }\nfunc main() { c := Counter{}; c.Inc(); fmt.Println(c.N) }', 'Добавьте метод Rename к структуре Task и проверьте, что новое имя видно после вызова.', 'Метод с указателем меняет исходное поле.', 'Какой получатель меняет исходную структуру?', '*Task', ['Task по значению', 'Любой метод без получателя']),
('Интерфейсы', 'Интерфейс описывает поведение через методы. Тип удовлетворяет интерфейсу неявно — отдельное объявление implements не нужно. Малые интерфейсы проще тестировать и повторно применять.', 'Значение интерфейса может хранить типизированный nil; простое сравнение с nil тогда даст false. Не вводите интерфейс заранее, если достаточно конкретного типа.', 'package main\nimport "fmt"\ntype Speaker interface { Speak() string }\ntype Cat struct{}\nfunc (Cat) Speak() string { return "мяу" }\nfunc main() { var s Speaker = Cat{}; fmt.Println(s.Speak()) }', 'Создайте второй тип, который реализует Speak, и функцию, принимающую Speaker.', 'Одна функция работает с обоими типами без изменений.', 'Как тип реализует интерфейс Go?', 'Набором нужных методов', ['Ключевым словом implements', 'Обязательным наследованием']),
('Ошибки как значения', 'В Go ошибка обычно возвращается отдельным значением error. Вызывающий код проверяет её сразу и решает, продолжать ли работу. fmt.Errorf с %w сохраняет цепочку причин для errors.Is и errors.As.', 'Не игнорируйте error через _. Не сравнивайте текст ошибки для выбора ветки, если доступна проверка типа или обёрнутого значения.', 'package main\nimport ("errors"; "fmt")\nfunc positive(n int) (int, error) { if n < 0 { return 0, errors.New("отрицательное") }; return n, nil }\nfunc main() { v, err := positive(2); fmt.Println(v, err) }', 'Напишите деление с ошибкой при нулевом делителе и проверьте успешный и ошибочный путь.', 'Нулевой делитель возвращает error, программа не паникует.', 'Как обычно сообщает о сбое функция Go?', 'Возвращает error', ['Всегда вызывает panic', 'Пишет только в журнал']),
('defer и закрытие ресурсов', 'defer откладывает вызов до выхода из текущей функции. Его часто ставят сразу после успешного открытия файла или ответа HTTP, чтобы гарантировать Close при любом последующем return.', 'Аргументы отложенного вызова вычисляются сразу. Если Open вернул ошибку, сначала проверьте её и только потом регистрируйте defer f.Close().', 'package main\nimport "fmt"\nfunc work() { defer fmt.Println("выход"); fmt.Println("работа") }\nfunc main() { work() }', 'Создайте функцию с двумя defer и проверьте порядок их выполнения.', 'Отложенные вызовы выполняются в обратном порядке.', 'Когда срабатывает defer?', 'При выходе из функции', ['Сразу при объявлении', 'Только после panic']),
('Пакеты и модули', 'Один модуль задаётся файлом go.mod; пакет состоит из файлов одного каталога. Импорт использует путь модуля и подпапку. Имена с заглавной буквы доступны другим пакетам; маленькие остаются внутри.', 'Не смешивайте package main и другой package в одной папке. go mod tidy обновляет зависимости и удаляет лишние записи, но не заменяет понимание импортов.', 'package main\nimport ("fmt"; "strings")\nfunc main() { fmt.Println(strings.ToUpper("go")) }', 'Создайте подпакет text с экспортируемой функцией и вызовите её из main; опишите путь импорта.', 'go run . собирает оба пакета модуля.', 'Что определяет go.mod?', 'Границу и путь модуля', ['Имя функции main', 'Порядок строк вывода']),
('Файлы и ввод/вывод', 'os.ReadFile и os.WriteFile подходят для небольших файлов; крупные данные лучше читать потоком. Всегда проверяйте ошибки: файл может отсутствовать, путь может быть недоступен, запись может быть неполной.', 'Не записывайте учебные файлы в произвольную системную папку. Используйте временный каталог для тестов, чтобы не повредить пользовательские данные.', 'package main\nimport ("fmt"; "os")\nfunc main() { name := "go-demo.txt"; if err := os.WriteFile(name, []byte("hello"), 0600); err != nil { panic(err) }; b, err := os.ReadFile(name); if err != nil { panic(err) }; fmt.Println(string(b)); _ = os.Remove(name) }', 'Запишите три строки в файл, прочитайте их обратно и отдельно обработайте отсутствие файла.', 'Прочитанные байты совпадают с записанными; отсутствие файла даёт error.', 'Какой тип возвращает os.ReadFile для содержимого?', '[]byte', ['string', 'int']),
('Тесты и табличные случаи', 'Файлы *_test.go запускаются командой go test ./...; Тест получает *testing.T; табличный тест перебирает пары входа и ожидаемого результата. Проверяйте обычные и граничные случаи, а не только один удачный пример.', 'Тест не должен зависеть от порядка map, текущего времени или сети без явной подмены. t.TempDir создаёт отдельный каталог для файлов и очищает его после теста.', 'package main\nimport "fmt"\nfunc square(n int) int { return n * n }\nfunc main() { for _, n := range []int{-2, 0, 3} { fmt.Println(square(n)) } }', 'Напишите square_test.go с таблицей для -2, 0 и 3; запустите go test ./...;', 'Все три тестовых случая проходят; неверный ожидаемый результат даёт понятную ошибку.', 'Как запустить тесты модуля?', 'go test ./...', ['go run tests', 'go check --all']),
('JSON: кодирование и декодирование', 'encoding/json превращает экспортируемые поля структур в JSON и обратно. json.Marshal возвращает байты и ошибку, json.Unmarshal требует указатель на место результата. Типы полей должны соответствовать ожидаемому документу.', 'Не принимайте непроверенный JSON как готовую бизнес-модель: после декодирования проверьте обязательные поля и диапазоны. Для HTTP ограничивайте размер тела запроса.', 'package main\nimport ("encoding/json"; "fmt")\ntype Note struct { Title string; Done bool }\nfunc main() { b, err := json.Marshal(Note{Title: "Go"}); fmt.Println(string(b), err) }', 'Сериализуйте две заметки, декодируйте результат и проверьте пустой заголовок отдельно.', 'После декодирования значения совпадают; пустой заголовок отклоняет ваша проверка.', 'Какие поля struct кодирует encoding/json?', 'Экспортируемые', ['Только строчные', 'Только числовые']),
('HTTP клиент', 'http.Client отправляет запросы и получает ответ со статусом и телом. Задайте timeout или context, проверьте ошибку транспорта и статус, затем закройте Body. Код 404 — успешный транспортный обмен, но не успешный результат задачи.', 'Не используйте http.Get без контроля времени в долгой работе. Не читайте бесконечное тело целиком от недоверенного сервера: ограничивайте размер.', 'package main\nimport ("fmt"; "net/http"; "time")\nfunc main() { c := &http.Client{Timeout: time.Second}; fmt.Println(c.Timeout > 0) }', 'Создайте клиент с таймаутом, запросите локальный тестовый сервер и обработайте статус 404.', 'Для 404 выводится отдельное сообщение; Body закрывается.', 'Что означает HTTP 404 для http.Client?', 'Ответ получен, ресурс не найден', ['Сеть обязательно недоступна', 'Паника Go']),
('HTTP сервер', 'net/http позволяет зарегистрировать обработчик и запустить сервер. Обработчик получает ResponseWriter и Request; метод и путь следует проверять явно. Для проверки используйте httptest, чтобы не открывать порт во время теста.', 'Не храните изменяемое состояние в глобальной map без защиты: HTTP запросы обрабатываются конкурентно. Ограничивайте размер тела и возвращайте понятные статусы ошибок.', 'package main\nimport ("fmt"; "net/http"; "net/http/httptest")\nfunc main() { h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "ok") }); w := httptest.NewRecorder(); h.ServeHTTP(w, httptest.NewRequest("GET", "/", nil)); fmt.Println(w.Code, w.Body.String()) }', 'Напишите обработчик GET /health, верните JSON и проверьте код и тело через httptest.', 'GET /health даёт 200 и корректный JSON; иной метод обрабатывается явно.', 'Как проверить обработчик без открытого порта?', 'Через httptest', ['Через fmt.Println', 'Только вручную в браузере']),
('Конфигурация приложения', 'Переменные окружения позволяют отделить настройки от кода. os.LookupEnv показывает, существует ли ключ; затем проверьте формат, диапазон и допустимые значения. Секреты никогда не печатайте в журнал и не кладите в репозиторий.', 'Для учебного сервера задайте безопасное значение по умолчанию только там, где оно действительно безопасно. Отсутствие обязательного секрета должно останавливать запуск с понятной ошибкой.', 'package main\nimport ("fmt"; "os")\nfunc main() { port, ok := os.LookupEnv("APP_PORT"); if !ok { port = "8080" }; fmt.Println(port) }', 'Добавьте APP_PORT с проверкой числа от 1 до 65535 и проверьте пустое, текстовое и допустимое значение.', 'Неверный порт отклоняется до запуска сервера.', 'Что возвращает os.LookupEnv вторым значением?', 'Признак наличия', ['Длину строки', 'HTTP статус']),
('Context и отмена', 'context.Context переносит дедлайн и сигнал отмены через цепочку вызовов. Передавайте его первым параметром и завершайте долгую работу при <-ctx.Done(). В HTTP сервере Request.Context отменяется, когда запрос заканчивается или клиент отключается.', 'Не храните Context в struct как постоянное состояние. Для context.WithTimeout всегда вызывайте cancel, чтобы освободить связанные ресурсы.', 'package main\nimport ("context"; "fmt"; "time")\nfunc main() { ctx, cancel := context.WithTimeout(context.Background(), time.Millisecond); defer cancel(); <-ctx.Done(); fmt.Println(ctx.Err()) }', 'Сделайте функцию ожидания с context и проверьте нормальное завершение и отмену.', 'После отмены функция возвращает context.Canceled или DeadlineExceeded.', 'Зачем нужен cancel после WithTimeout?', 'Освободить ресурсы и сообщить об отмене', ['Ускорить компиляцию', 'Удалить go.mod']),
('Горутины и ожидание', 'go запускает функцию как горутину. Она может выполняться одновременно с другими, но порядок запуска и вывода не гарантируется. sync.WaitGroup помогает дождаться окончания набора задач перед выходом из main.', 'time.Sleep не является надёжным способом дождаться горутин. Ошибки и жизненный цикл задач нужно продумывать отдельно, иначе фоновая работа теряется при завершении программы.', 'package main\nimport ("fmt"; "sync")\nfunc main() { var wg sync.WaitGroup; wg.Add(1); go func() { defer wg.Done(); fmt.Println("готово") }(); wg.Wait() }', 'Запустите три горутины с номерами, дождитесь их через WaitGroup и объясните, почему порядок вывода меняется.', 'Каждый номер выводится ровно один раз; main не завершается раньше задач.', 'Чем дождаться завершения нескольких горутин?', 'sync.WaitGroup', ['time.Sleep как гарантией', 'append']),
('Каналы', 'Канал передаёт типизированные значения между горутинами. Небуферизованный канал синхронизирует отправителя и получателя; буферизованный допускает ограниченное число отправок без немедленного чтения.', 'Не закрывайте канал со стороны получателя, если отправители ещё могут писать. Отправка в закрытый канал вызывает panic, поэтому ответственность за закрытие должна быть ясной.', 'package main\nimport "fmt"\nfunc main() { ch := make(chan int); go func() { ch <- 7 }(); fmt.Println(<-ch) }', 'Передайте через канал сумму двух чисел из отдельной горутины и проверьте результат.', 'Получатель печатает сумму; программа завершается без ожидания через Sleep.', 'Что делает чтение из пустого небуферизованного канала?', 'Ждёт отправителя', ['Возвращает 0 сразу', 'Закрывает канал']),
('select и таймаут', 'select ждёт готовности одного из нескольких операций с каналами. Вместе с ctx.Done() он позволяет остановить ожидание при отмене; time.NewTimer задаёт ограничение времени.', 'Если всегда выбирать default, цикл может непрерывно нагружать процессор. Останавливайте таймер и учитывайте, кто закрывает канал.', 'package main\nimport ("fmt"; "time")\nfunc main() { select { case <-time.After(time.Millisecond): fmt.Println("таймаут") } }', 'Сделайте ожидание результата с таймаутом и отдельно проверьте быстрый ответ и отсутствие ответа.', 'Быстрый ответ возвращает значение; медленный путь завершается по времени.', 'Для чего применяют select?', 'Ждать несколько операций с каналами', ['Создавать struct', 'Импортировать пакет']),
('Общая память и гонки', 'Если несколько горутин изменяют одну переменную, без синхронизации результат непредсказуем. sync.Mutex защищает критическую секцию; go test -race или go run -race помогает обнаружить гонку во время выполнения.', 'Не считайте map потокобезопасной для конкурентной записи. Мьютекс защищает только те обращения, которые действительно проходят через него; тестируйте и чтение, и запись.', 'package main\nimport ("fmt"; "sync")\nfunc main() { var mu sync.Mutex; n := 0; var wg sync.WaitGroup; for i := 0; i < 2; i++ { wg.Add(1); go func() { defer wg.Done(); mu.Lock(); n++; mu.Unlock() }() }; wg.Wait(); fmt.Println(n) }', 'Запустите 100 инкрементов из горутин, защитите счётчик и проверьте через go run -race .', 'Счётчик равен 100; race detector не сообщает о гонке.', 'Чем защищают общую переменную при записи?', 'sync.Mutex', ['fmt.Println', 'Незащищённой map']),
('database/sql и модель данных', 'database/sql задаёт общий интерфейс к SQL, но конкретный драйвер подключается отдельно. Подготовленные параметры отделяют данные от текста запроса. Контекст и закрытие rows важны для запросов, которые могут ждать сеть или возвращать много строк.', 'Не складывайте все поля сущности в одну текстовую колонку. Темы нормализации и индексов из канала Нияза полезны для разбора схемы, но учебный проект сначала должен корректно хранить данные.', 'package main\nimport ("database/sql"; "fmt")\nfunc main() { var db *sql.DB; fmt.Println(db == nil) }', 'Нарисуйте таблицу tasks(id, title, done), два SQL запроса с параметрами и объясните, когда понадобится индекс.', 'Схема отделяет поля; запрос не конкатенирует пользовательский ввод в SQL.', 'Что нужно database/sql для реального соединения?', 'Драйвер конкретной БД', ['Только fmt', 'HTTP обработчик']),
('Проект: модель задач', 'Итоговый проект — небольшой API задач. Сначала определите Task с ID, заголовком и статусом; отдельно задайте правила: заголовок не пустой, ID уникален, неизвестная задача возвращает понятную ошибку.', 'Не начинайте с роутов до модели и правил данных. Тестируйте модель отдельно: пустой заголовок, повторный ID, переход статуса и отсутствующая запись.', 'package main\nimport "fmt"\ntype Task struct { ID int; Title string; Done bool }\nfunc main() { t := Task{ID: 1, Title: "Изучить Go"}; fmt.Println(t.ID, t.Title, t.Done) }', 'Опишите модель и функцию Validate, возвращающую error для пустого заголовка.', 'Корректная задача проходит, пустой заголовок отклоняется.', 'Что проверить до сохранения задачи?', 'Правила модели', ['Только цвет кнопки', 'Порядок полей JSON']),
('Проект: HTTP API', 'Добавьте GET /tasks для списка и POST /tasks для создания. Декодируйте JSON с ограничением размера, проверьте модель, выставьте Content-Type и верните соответствующий статус. Разделите обработчик и хранение за маленьким интерфейсом.', 'Не возвращайте 200 для всех ошибок. Неверный JSON — ошибка клиента; неожиданная ошибка хранилища — ошибка сервера без утечки внутренних деталей.', 'package main\nimport ("fmt"; "net/http"; "net/http/httptest")\nfunc main() { h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.Header().Set("Content-Type", "application/json"); fmt.Fprint(w, "[]") }); w := httptest.NewRecorder(); h.ServeHTTP(w, httptest.NewRequest("GET", "/tasks", nil)); fmt.Println(w.Code, w.Body.String()) }', 'Сделайте GET и POST, проверьте успешный запрос, пустой заголовок и неверный JSON.', 'Успех возвращает JSON; неверный ввод даёт 400.', 'Какой статус подходит неверному JSON клиента?', '400', ['200', '500 всегда']),
('Проект: хранение и ошибки', 'Для первой версии допустимо хранение в памяти за интерфейсом Repository. После этого можно подключить SQL драйвер и миграции, не меняя правила HTTP. Ошибку «не найдено» отделите от системного сбоя.', 'Если хранилище — map, защитите его mutex от конкурентных запросов. Не обещайте сохранность после перезапуска до подключения постоянной базы.', 'package main\nimport ("fmt"; "sync")\ntype Store struct { mu sync.Mutex; items map[int]string }\nfunc main() { s := Store{items: map[int]string{1: "Go"}}; s.mu.Lock(); fmt.Println(s.items[1]); s.mu.Unlock() }', 'Добавьте потокобезопасные Create и Get и тест на неизвестный ID.', 'Созданная задача читается; неизвестный ID возвращает отдельную ошибку.', 'Что защищает map от конкурентной записи?', 'Мьютекс вокруг доступа', ['Только defer', 'Название Repository']),
('Проект: тесты обработчиков', 'httptest.NewRecorder и httptest.NewRequest проверяют HTTP без реального порта. Табличные тесты фиксируют метод, путь, тело, ожидаемый статус и JSON. Подменное хранилище помогает проверить отказ без настоящей базы.', 'Тестируйте не только статус: сравните Content-Type, тело и отсутствие утечки внутренней ошибки. Повторный запуск должен давать тот же результат.', 'package main\nimport ("fmt"; "net/http"; "net/http/httptest")\nfunc main() { h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(http.StatusCreated) }); w := httptest.NewRecorder(); h.ServeHTTP(w, httptest.NewRequest("POST", "/tasks", nil)); fmt.Println(w.Code) }', 'Напишите тесты для GET 200, POST 201, пустого заголовка 400 и ошибки хранилища 500.', 'Все четыре сценария проходят в go test ./...;', 'Какой пакет тестирует HTTP обработчик локально?', 'net/http/httptest', ['os/exec', 'encoding/csv']),
('Проект: запуск и итоговая проверка', 'Соберите проект через go build ./..., запустите тесты через go test ./... и отдельно проверьте гонки через go test -race ./...; Завершите API задач: модель, валидация, GET и POST, хранение и инструкции запуска.', 'Проверьте занятый порт и неверные запросы. Курс даёт самостоятельную практику, но платформа не выполняет ваш код и не выдаёт экспертную оценку. В README опишите ограничения и выберите одно расширение.', 'package main\nimport ("fmt"; "runtime")\nfunc main() { fmt.Println("Go", runtime.Version()) }', 'Соберите API, запустите тесты и race detector, добавьте README с командами и одно расширение: поиск, обновление статуса либо постоянное хранение.', 'Другой человек может локально запустить и проверить проект по README; сборка и тесты проходят.', 'Чем обнаруживать гонки в тестах?', 'go test -race ./...', ['go fmt -race', 'go mod tidy -race']),
]

# The public channel highlights these topics. These paragraphs are original
# explanations; no post, attachment or paid lesson is reproduced here.
CHANNEL_TOPICS = {
    7: 'В публичном канале Нияза отдельно разбираются подводные камни map: порядок range, рост таблицы и конкурентные записи. Для практического кода главное правило проще: не предполагайте порядок, проверяйте наличие через ok и синхронизируйте общий доступ. Внутреннее устройство зависит от версии Go, поэтому этот урок не привязывает поведение программы к устройству бакетов.',
    21: 'Публичный разбор планировщика Go объясняет модель G/M/P: горутины распределяются по потокам ОС через логические процессоры, а ожидающая ввод-вывод работа освобождает ресурсы для других задач. Это помогает понять, почему запуск go func() не обещает немедленного или упорядоченного выполнения. Практический вывод: задавайте завершение и отмену явно.',
    24: 'Тема конкурентных ошибок из материалов канала применима к счётчику и общей map. Race detector находит только гонки, которые реально случились во время запуска теста; отсутствие сообщения не является математическим доказательством безопасности. Проверьте каждый путь чтения и записи через один механизм синхронизации.',
    25: 'В открытых публикациях Нияза есть разборы нормализации и индексов БД. В учебном сервисе отделяйте сущности по смыслу, не дублируйте изменяемые значения без причины и измеряйте запросы перед добавлением индекса. Индекс ускоряет некоторые чтения, но занимает место и добавляет работу при записи; он не исправляет неверную модель данных.',
}
CHAPTERS = ['Старт', 'Структуры данных', 'Надёжный код', 'Прикладной Go', 'Параллельность и хранение', 'Итоговый проект']

def build():
    course = json.loads(TARGET.read_text(encoding='utf-8'))
    lessons = []
    for index, (title, concept, caveat, example, practice, expected, question, correct, wrong) in enumerate(LESSONS, 1):
        options = [correct, *wrong]
        rotation = index % len(options)
        options = options[rotation:] + options[:rotation]
        lessons.append({
            'id': f'go-{index:02d}', 'title': title, 'level': 'beginner', 'minutes': 45,
            'chapter': f'Глава {(index - 1) // 5 + 1}: {CHAPTERS[(index - 1) // 5]}',
            'explanation': [concept, caveat + ' Выполните пример локально командой go run . в учебном модуле. После запуска измените один вход и сравните фактический результат с ожидаемым.'] + ([CHANNEL_TOPICS[index]] if index in CHANNEL_TOPICS else []),
            'example': example, 'practice': practice, 'solution': expected,
            **({'related_source': {'label': 'Публикации Нияза по теме', 'url': 'https://t.me/niyaz_golang'}} if index in CHANNEL_TOPICS else {}),
            'rubric': ['Пример запущен локально или разобран по шагам с точным выводом.', 'Практика проверена на обычном и граничном случае.', 'Результат и причина ошибки объяснены своими словами.'],
            'quiz': [
                {'prompt': question, 'options': options, 'answers': [correct], 'explanation': concept, 'skill': 'code'},
                {'prompt': f'Какой результат должен получиться в практике «{title}»?', 'options': [expected, 'Программа должна завершиться без проверки результата.', 'Достаточно прочитать объяснение, не выполняя упражнение.'], 'answers': [expected], 'explanation': expected + ' Практическую часть оцените по рубрике после фактического запуска.', 'skill': 'practice'},
            ],
            'retry_practice': f'Повторите занятие {index}: {practice} Если результат отличается, сохраните вход, команду, ошибку и исправление.'
        })
    course['lessons'] = lessons
    TARGET.write_text(json.dumps(course, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

if __name__ == '__main__':
    build()
